export interface PrintBlock {
  readonly id: string;
  readonly kind: "hospital" | "title" | "patient" | "table" | "totals" | "signature" | "barcode" | "note" | "footer" | "watermark";
  /** Millimetres from the left edge */
  readonly x: number;
  /** Millimetres from the top edge */
  readonly y: number;
  /** Width in millimetres */
  readonly w: number;
  /** Height in millimetres */
  readonly h: number;
  readonly align?: "left" | "centre" | "right";
  /** A type scale rather than pixels: the renderer decides what `md` is on a card and on a sheet */
  readonly size?: "sm" | "md" | "lg";
  readonly bold?: boolean;
  /** The words, for a block that carries its own */
  readonly text?: string;
  /** The register field a data block reads; unset means the block would print its heading and a blank */
  readonly field?: "patient.identity" | "patient.contact" | "patient.allergy" | "visit.identity" | "record.number" | "invoice.lines" | "invoice.totals" | "prescription.medicines" | "lab.results" | "discharge.course" | "birth.record" | "death.record" | "staff.member" | "attendance.month" | "pass.number";
  /** How many rows a table prints */
  readonly rows?: number;
}

export interface PrintTemplate {
  readonly id: string;
  readonly name: string;
  readonly paper: "a4-portrait" | "a4-landscape" | "a5-portrait" | "thermal-80" | "card-cr80" | "label-50x25";
  /** The version this node prints from; zero means nothing has been published and the code template still prints */
  readonly version: number;
  readonly publishedAt?: string;
  readonly publishedBy?: string;
  readonly blocks?: Array<PrintBlock>;
}

export interface PrintTemplateVersion {
  readonly paper: "a4-portrait" | "a4-landscape" | "a5-portrait" | "thermal-80" | "card-cr80" | "label-50x25";
  /** The whole layout, not a patch: a version is a sheet of paper, and half a sheet is not a version */
  readonly blocks: Array<PrintBlock>;
  /** What changed, in the words of the person who changed it */
  readonly note?: string;
  readonly publishedBy: string;
}

export interface ScheduleCadence {
  /** How often, and the weekday or day of the month below carries the rest */
  readonly id: "daily" | "weekly" | "monthly";
  /** `HH:MM` on the branch’s own clock; a sheet sent twice a day carries both times */
  readonly times: Array<string>;
  /** Weekly: 0–6 with Sunday as 0, the week this branch works */
  readonly weekdays?: Array<number>;
  /** Monthly: 1–28. Beyond that a month is skipped, which is refused rather than accepted */
  readonly day?: number;
  /** Monthly: the first day that is neither a weekend nor a gazetted holiday, read from the branch’s calendar */
  readonly firstWorkingDay?: boolean;
  /** Why that time, in the branch’s words — the register’s own sentence where it has one */
  readonly because?: string;
}

export interface ScheduleRecipient {
  readonly name: string;
  readonly role?: string;
  readonly channel: "print-desk" | "hospital-mail" | "public-mail" | "whatsapp";
  /** Where the channel needs one; a counter that picks the sheet up has none */
  readonly address?: string;
}

export interface ReportSchedule {
  readonly id: string;
  /** A topic the report register holds; an invented one is refused */
  readonly topic: string;
  /** A branch, or `All branches` for the consolidated figure */
  readonly scope: string;
  readonly range: "today" | "week" | "month";
  readonly cadence: ScheduleCadence;
  readonly format: "csv" | "print";
  readonly recipients: Array<ScheduleRecipient>;
  /** What the receiver does with it; a report nobody acts on is a report nobody reads */
  readonly action: string;
  readonly sendWhen: "always" | "when-there-is-a-row";
  readonly owner: string;
  /** A paused schedule keeps its settings, its place and its history */
  readonly enabled: boolean;
  readonly savedAt?: string;
  readonly savedBy?: string;
}

export interface ReportRunRequest {
  /** The branch day the report is read for */
  readonly day: string;
  /** Render the file and report what it holds without sending it — what the schedule screen does at the desk */
  readonly dryRun?: boolean;
}

export interface ReportRun {
  readonly id: string;
  readonly scheduleId: string;
  readonly day: string;
  readonly startedAt: string;
  readonly finishedAt?: string;
  readonly dryRun?: boolean;
  readonly rows: number;
  readonly bytes?: number;
  /** The name the file went out under */
  readonly file?: string;
  /** The sentence the run was skipped with, when the schedule says it only goes out with something to report */
  readonly skipped?: string;
  readonly recipients: Array<{ name: string; channel: "print-desk" | "hospital-mail" | "public-mail" | "whatsapp"; sentAt: string; receipt: string; failed: string }>;
}

export interface ReportColumn {
  readonly key: string;
  readonly header: string;
  readonly align?: "left" | "right";
  readonly width?: string;
  readonly kind?: "money" | "count" | "text" | "percent";
  /** How the column adds up across rows and branches; an age stays a maximum */
  readonly aggregate?: "sum" | "max";
  readonly percentOf?: { part: string; whole: string };
  readonly avgOf?: { total: string; count: string; suffix: string };
}

export interface ReportRow {
  readonly id: string;
  readonly label: string;
  readonly cells: Record<string, unknown>;
  /** On a consolidated row: the figure each branch contributed, which is what makes the total checkable rather than asserted */
  readonly from?: Record<string, number>;
}

export interface ReportAggregate {
  readonly topic: string;
  readonly title: string;
  readonly scope: string;
  readonly range: "today" | "week" | "month";
  /** The branch day the report was read for */
  readonly asOf: string;
  /** The days actually read — `min(the range asked for, what the data holds)`, named rather than implied */
  readonly daysRead: Array<string>;
  readonly rangeNote?: string;
  readonly columns: Array<ReportColumn>;
  readonly rows: Array<ReportRow>;
  readonly totals: Record<string, number>;
  /** Branches that cannot answer this report at all, with the reason — printed instead of a row of zeros */
  readonly unavailable?: Array<{ branch: string; because: string }>;
  /** The control total the figures have to agree with, as the sentence the reader checks them against */
  readonly closing: string;
  /** How the consolidated figure was arrived at, branch by branch */
  readonly reconciliation: string;
  readonly computedAt: string;
  /** Which tier answered: the canonical computation, or this branch's own replica while the uplink is down */
  readonly computedBy: "cloud" | "edge";
  /** The replication watermark the figures were read at, so a reader can tell whether the last admission is in them */
  readonly registerAt: string;
}

/** Who this token belongs to, and what its roles may do — read out of `x-dizi-roles` rather than described again here, so the answer a person sees on screen is the answer the API enforces. */
export interface Me {
  /** The token subject: the account, not the person’s name. */
  readonly actor: string;
  readonly name: string;
  /** Every role the token carries that the contract declares, widest first. A role outside the table is refused rather than listed. */
  readonly roles: Array<RoleInToken>;
  /** The union of the abilities of those roles — what this session may do here and now. */
  readonly abilities: Array<"read" | "write" | "administer">;
  /** The branch this account works in, from the token. Empty when the realm does not map it, which is a realm that needs its branch mapper rather than a bug here. */
  readonly branch: string;
  readonly node: string;
  /** Who signed the token, so a log line answers “was this the edge realm or the cloud one”. */
  readonly issuer: string;
  readonly driver: "preview" | "keycloak";
  /** How many screens the legacy system reached with the widest role held, from `docs/FEATURE-CATALOG.md` §5. Zero for a role the legacy system did not have. */
  readonly legacyScreens: number;
}

/** One role, as the contract declares it. */
export interface RoleInToken {
  /** The realm role name, e.g. `receptionist`. */
  readonly id: string;
  readonly label: { en: string; bn: string };
  /** The app shell this role renders as. A shell is navigation, not a permission. */
  readonly shell: "receptionist" | "doctor" | "pharmacist" | "billing" | "admin";
  readonly abilities: Array<"read" | "write" | "administer">;
}

export interface AppointmentSlot {
  readonly start: string;
  /** Minutes from midnight, local: the slot's own clock face, so a calendar can draw it without parsing the timestamp. */
  readonly minutes: number;
  readonly state: "free" | "booked";
  /** Which appointment holds it, when one does. */
  readonly appointmentId?: string;
  /** The queue token that appointment was given, which is what the board calls the patient. */
  readonly token?: string;
  /** How long the appointment holding it runs for; a booked slot is the first of its claimed steps. */
  readonly durationMin?: number;
}

export interface AppointmentSlotDay {
  readonly day: string;
  readonly doctorId: string;
  readonly room?: string;
  readonly slotMinutes: number;
  /** How many consecutive slots a consultation at this sitting claims. It is roster data rather than a product constant: a cardiology clinic books four steps where a paediatric one books two, and a sheet that guesses would offer a block the service then refuses. */
  readonly claimStarts: number;
  /** Whether the clinic is open: a closed day is a 200 with no slots and the reason, not a 404. */
  readonly open?: boolean;
  readonly closedBecause?: unknown;
  readonly window?: { from: number; to: number };
  readonly slots: Array<AppointmentSlot>;
  readonly asOf?: string;
}

/** One attempt to deliver one message. Appended, never edited: a retry is the next row, and the row before it keeps the provider’s words. */
export interface NotificationDelivery {
  readonly id: string;
  readonly eventId?: string;
  /** The event this message is about, as `x-dizi-notifications.events` names it. */
  readonly topic: string;
  readonly channel: "whatsapp" | "email";
  readonly template: string;
  readonly language: "bn" | "en";
  /** The patient, when the event is about one. Staff notifications have none. */
  readonly mrn?: unknown;
  /** Where it went, masked: a delivery log is read by whoever is on duty, and a log full of phone numbers is a patient register in a second place. The last three characters are kept so a patient asking “did it go to the right number?” can be answered. */
  readonly to: string;
  /** `suppressed` is a policy refusal — no consent, no address, quiet hours, an unapproved template — and it is not a fault of the channel. `sent` means the provider accepted it; `delivered` and `read` come from the provider’s own receipts. */
  readonly status: "queued" | "sent" | "delivered" | "read" | "failed" | "suppressed";
  /** Which driver carried it: `meta-cloud`, `smtp`, or `preview` — and `preview` means nothing left this node. The delivery log says which is in force at the top rather than leaving a reader to infer it from the rows. */
  readonly provider: string;
  readonly providerMessageId?: unknown;
  /** A `dizi.*` code when the attempt failed or was suppressed. */
  readonly errorCode?: unknown;
  /** The sentence a person reads: what happened, in the service’s or the provider’s own words. */
  readonly detail?: unknown;
  readonly attempt: number;
  readonly at: string;
  /** Whether a person may retry it: a failed attempt with attempts left. A suppression is not retryable — pressing retry does not create consent. */
  readonly retryable: boolean;
}

export interface NotificationDeliveryPage {
  readonly rows: Array<NotificationDelivery>;
  readonly asOf: string;
  /** Which driver is in force per channel. `preview` renders the message, records what it would have sent and touches no network — a log of preview rows is not evidence that anybody was told. */
  readonly driver: { whatsapp: string; email: string };
  /** Channels that are not delivering: at least `x-dizi-notifications.alerting.consecutiveFailures` failures inside the window. Suppressions do not count — a policy refusal is not a channel that is down. */
  readonly alerts: Array<{ channel: string; failures: number; since: string; because: string }>;
  /** How many of the returned rows are in each status, so a screen prints the shape of a morning without counting. A status with no rows is absent rather than zero. */
  readonly counts?: Record<string, number>;
}

/** One template, in one language, for one channel. `x-dizi-notifications.templates` is the pilot’s default wording and this is what the branch’s own registry says. */
export interface NotificationTemplate {
  readonly event: string;
  readonly template: string;
  readonly channel: "whatsapp" | "email";
  readonly language: "bn" | "en";
  /** E-mail only; a WhatsApp template has no subject. */
  readonly subject?: unknown;
  readonly body: string;
  readonly placeholders: Array<string>;
  /** WhatsApp templates are approved by Meta per account; e-mail needs none. `pending` and `rejected` both refuse a send, with different sentences. */
  readonly approval: "not-required" | "pending" | "approved" | "rejected";
  readonly enabled: boolean;
}

export interface NotificationTemplatePage {
  readonly rows: Array<NotificationTemplate>;
  /** The catalogue, from the contract: every event the node notices, the template it is said in, and the events that are deliberately not notifiable. */
  readonly events: Array<{ topic: string; template: unknown; channels: Array<string>; notifiable: boolean; means: string }>;
  readonly asOf: string;
}


/* ------------------------------------------------------------- operations */

export type OfflineCapability = "online-only" | "cache" | "queue";
export type Authority = "cloud" | "edge";
export type Idempotency = "none" | "required";
export type EntityKind = keyof typeof entityPolicies;
export type DrainOutcome = keyof typeof drainOutcomes;

export interface OperationMeta {
  readonly id: string;
  readonly method: string;
  readonly path: string;
  readonly tag: string | null;
  readonly summary: string | null;
  /** The conflict policy that applies to this operation's record, or null for the platform endpoints. */
  readonly entity: EntityKind | null;
  /** cache: serve the read from the replica. queue: queue the write and replay it. online-only: refuse it, with a reason. */
  readonly offline: OfflineCapability;
  readonly authority: Authority;
  readonly idempotency: Idempotency;
  readonly audit: boolean;
  /** Shown to staff when the app refuses the action: the reason in their words, not an error code. */
  readonly because: string | null;
  /** Present on every online-only operation: why it cannot be queued. */
  readonly notes: string | null;
  readonly request: string | null;
  readonly responses: Readonly<Record<string, string | null>>;
  readonly problemResponses: readonly string[];
  readonly statuses: readonly number[];
  readonly mayQueue: boolean;
  readonly servesFromReplica: boolean;
  readonly needsNetwork: boolean;
  readonly requiresIdempotencyKey: boolean;
}

