export const drainOutcomes = {
  "applied": {
    "status": "2xx",
    "meaning": "The write is in the canonical record.",
    "client": "The outbox entry is dropped and the screen stops marking the row as local."
  },
  "duplicate": {
    "status": "2xx replay, or 409 with problem type dizi.duplicate-operation",
    "meaning": "This Idempotency-Key was already applied, so nothing changed and the original response is returned.",
    "client": "The outbox entry is dropped: a drain that ran twice must not write twice."
  },
  "conflict": {
    "status": "409 with `conflict`, `candidates` or `alternatives`",
    "meaning": "A person has to decide. Both values are returned; nothing is merged silently.",
    "client": "The operation leaves the automatic queue and appears in the review list until someone resolves it."
  },
  "refused": {
    "status": "4xx (422, 404, 403) other than a conflict",
    "meaning": "The write will never be accepted as it stands.",
    "client": "Shown to the desk with the reason and the original entry: retrying it automatically would only hide it."
  },
  "deferred": {
    "status": "503, 504, any other 5xx, or a timeout",
    "meaning": "The cloud tier is not reachable, or the server failed in a way that says nothing about the write. A bare 500 is the server’s problem rather than a verdict on the request.",
    "client": "The operation keeps its place in the queue, and the queue keeps its order. Retrying is safe because every queued write carries an Idempotency-Key."
  }
} as const;

